def upgrade() -> None:
    """Создаёт независимые источники без изменения существующих бизнес-данных."""
    for statement in DDL:
        op.execute(statement)


def downgrade() -> None:
    """Откат пустой схемы; сохранённые snapshots/links/credentials не удаляются."""
    bind = op.get_bind()
    if any(
        bind.execute(sa.text(f'SELECT EXISTS (SELECT 1 FROM "{name}" LIMIT 1)')).scalar()
        for name in TABLES
    ):
        raise RuntimeError("Откат Git запрещён: сохранены источники или доказательства.")
    for name in reversed(TABLES):
        op.drop_table(name)
